/**
 * Photorealistic Google Map3DElement host for Watch chase.
 * Terrain mesh is worldwide; building/tree surface data is coverage-limited.
 */

export type Map3DCamera = {
  lat: number;
  lng: number;
  heading?: number;
  tilt?: number;
  /** Camera distance from look-at point in meters. */
  range?: number;
  /** Look-at altitude in meters (0 ≈ ground). */
  altitude?: number;
};

type Maps3dLib = {
  Map3DElement: new (opts?: Record<string, unknown>) => HTMLElement & {
    mode: string;
    center: { lat: number; lng: number; altitude?: number };
    heading: number;
    tilt: number;
    range: number;
    append: (...nodes: Node[]) => void;
  };
  Polyline3DElement: new (opts?: Record<string, unknown>) => HTMLElement & {
    coordinates: Array<{ lat: number; lng: number; altitude?: number }>;
    strokeColor: string;
    strokeWidth: number;
    altitudeMode: string;
    drawsOccludedSegments?: boolean;
  };
  Marker3DElement: new (opts?: Record<string, unknown>) => HTMLElement & {
    position: { lat: number; lng: number; altitude?: number };
    altitudeMode: string;
    extruded?: boolean;
  };
  AltitudeMode?: { RELATIVE_TO_MESH: string; CLAMP_TO_GROUND: string; ABSOLUTE: string };
  MapMode?: { HYBRID: string; SATELLITE: string };
};

let maps3dPromise: Promise<Maps3dLib | null> | null = null;

/** Load maps3d library once; returns null when WebGL / API cannot start Map3D. */
export async function loadMaps3dLibrary(): Promise<Maps3dLib | null> {
  if (maps3dPromise) return maps3dPromise;
  maps3dPromise = (async () => {
    try {
      if (!window.google?.maps?.importLibrary) return null;
      const lib = (await window.google.maps.importLibrary("maps3d")) as Maps3dLib;
      if (!lib?.Map3DElement) return null;
      return lib;
    } catch (err) {
      console.warn("[mmd] maps3d unavailable", err);
      return null;
    }
  })();
  return maps3dPromise;
}

/** Approximate Mapbox zoom → Map3D camera range (meters). */
export function zoomToMap3dRange(zoom: number, pitch = 50): number {
  const z = Math.max(4, Math.min(18, zoom || 10));
  // Cab / live-nav: keep the camera close enough to read the road surface.
  // Previous curve left city-scale altitudes (~1–3 km) on highway legs.
  const base = 95000 / Math.pow(2, z - 5);
  const pitchFactor = pitch >= 60 ? 0.55 : pitch >= 52 ? 0.62 : pitch >= 48 ? 0.72 : 0.85;
  return Math.max(55, Math.min(8000, base * pitchFactor));
}

export class ImmersiveGoogle3D {
  private host: HTMLElement;
  private mapEl: HTMLElement | null = null;
  private trailEl: (HTMLElement & { coordinates: unknown }) | null = null;
  private markerEl: (HTMLElement & { position: unknown }) | null = null;
  private lib: Maps3dLib | null = null;
  private active = false;
  private trailColor = "#38bdf8";

  constructor(hostParent: HTMLElement) {
    this.host = document.createElement("div");
    this.host.id = "map-3d-immersive";
    this.host.className = "map-3d-immersive";
    this.host.setAttribute("aria-hidden", "true");
    hostParent.appendChild(this.host);
  }

  isActive(): boolean {
    return this.active && !!this.mapEl;
  }

  async enable(): Promise<boolean> {
    if (this.active && this.mapEl) return true;
    this.lib = await loadMaps3dLibrary();
    if (!this.lib) return false;

    try {
      const mode = this.lib.MapMode?.HYBRID || "HYBRID";
      const map = new this.lib.Map3DElement({
        mode,
        center: { lat: 39.1, lng: -106.8, altitude: 0 },
        heading: 0,
        tilt: 67.5,
        range: 2500,
        gestureHandling: "GREEDY",
        defaultUIHidden: true,
      });
      map.style.cssText = "position:absolute;inset:0;width:100%;height:100%;border:0;";
      this.host.innerHTML = "";
      this.host.appendChild(map);
      this.mapEl = map;
      document.body.classList.add("google-immersive-booting");

      const alt =
        this.lib.AltitudeMode?.RELATIVE_TO_MESH ||
        this.lib.AltitudeMode?.CLAMP_TO_GROUND ||
        "RELATIVE_TO_MESH";

      const trail = new this.lib.Polyline3DElement({
        altitudeMode: alt,
        strokeColor: this.trailColor,
        strokeWidth: 12,
        drawsOccludedSegments: true,
        // Non-geodesic: follow the densified road polyline instead of
        // great-circle chords between sparse Mapbox vertices.
        geodesic: false,
      });
      // Do not assign an empty path — Map3D throws InvalidValueError on empty iterables.
      map.append(trail);
      this.trailEl = trail;

      // Default Marker3DElement pin only — custom slotted HTML requires PinElement.
      const marker = new this.lib.Marker3DElement({
        altitudeMode: alt,
        extruded: true,
        position: { lat: 39.1, lng: -106.8, altitude: 8 },
      });
      map.append(marker);
      this.markerEl = marker;

      // Wait for WebGL canvas — Cloud/software GL often fails Map3D silently.
      const ready = await this.waitForMap3dCanvas(map, 4500);
      document.body.classList.remove("google-immersive-booting");
      if (!ready) {
        console.warn("[mmd] Map3D WebGL canvas never appeared — falling back to hybrid");
        this.disable();
        return false;
      }

      this.active = true;
      this.host.setAttribute("aria-hidden", "false");
      document.body.classList.add("google-immersive-3d", "google-map3d-ready");
      return true;
    } catch (err) {
      document.body.classList.remove("google-immersive-booting");
      console.warn("[mmd] Map3DElement failed to start", err);
      this.disable();
      return false;
    }
  }

  private waitForMap3dCanvas(root: HTMLElement, timeoutMs: number): Promise<boolean> {
    return new Promise((resolve) => {
      const start = performance.now();
      const tick = () => {
        const canvas =
          root.querySelector("canvas") ||
          this.host.querySelector("canvas") ||
          // Some builds render into shadow root
          (root.shadowRoot && root.shadowRoot.querySelector("canvas"));
        if (canvas) {
          resolve(true);
          return;
        }
        if (performance.now() - start > timeoutMs) {
          resolve(false);
          return;
        }
        requestAnimationFrame(tick);
      };
      tick();
    });
  }

  disable(): void {
    this.active = false;
    document.body.classList.remove(
      "google-immersive-3d",
      "google-map3d-ready",
      "google-immersive-booting",
    );
    this.host.setAttribute("aria-hidden", "true");
    this.host.innerHTML = "";
    this.mapEl = null;
    this.trailEl = null;
    this.markerEl = null;
  }

  setCamera(cam: Map3DCamera): void {
    if (!this.active || !this.mapEl) return;
    const el = this.mapEl as HTMLElement & {
      center: { lat: number; lng: number; altitude?: number };
      heading: number;
      tilt: number;
      range: number;
    };
    try {
      el.center = {
        lat: cam.lat,
        lng: cam.lng,
        altitude: cam.altitude ?? 0,
      };
      if (cam.heading != null) el.heading = ((cam.heading % 360) + 360) % 360;
      if (cam.tilt != null) el.tilt = Math.max(0, Math.min(82, cam.tilt));
      if (cam.range != null) el.range = Math.max(80, cam.range);
    } catch (err) {
      console.warn("[mmd] Map3D camera update failed", err);
    }
  }

  setTrail(
    coords: Array<[number, number] | { lng: number; lat: number }>,
    color?: string,
  ): void {
    if (!this.trailEl) return;
    if (color) {
      this.trailColor = color;
      try {
        (this.trailEl as unknown as { strokeColor: string }).strokeColor = color;
      } catch {
        /* ignore */
      }
    }
    const path = coords
      .map((c) =>
        Array.isArray(c)
          ? { lat: Number(c[1]), lng: Number(c[0]), altitude: 4 }
          : { lat: Number(c.lat), lng: Number(c.lng), altitude: 4 },
      )
      .filter((c) => Number.isFinite(c.lat) && Number.isFinite(c.lng));
    if (path.length < 2) return;
    try {
      const el = this.trailEl as unknown as {
        path?: unknown;
        coordinates?: unknown;
      };
      // Prefer `path` (coordinates is deprecated on Polyline3DElement).
      if ("path" in el || typeof (el as { path?: unknown }).path !== "undefined") {
        el.path = path;
      } else {
        el.coordinates = path;
      }
    } catch (err) {
      console.warn("[mmd] Map3D trail update failed", err);
    }
  }

  setPlayhead(lat: number, lng: number, _heading?: number): void {
    if (!this.markerEl) return;
    try {
      this.markerEl.position = { lat, lng, altitude: 10 };
    } catch {
      /* ignore */
    }
  }

  destroy(): void {
    this.disable();
    this.host.remove();
  }
}
