/** Map basemap provider preference (display only — routes stay precomputed). */

export type MapProviderId = "mapbox" | "google";

export const MAP_PROVIDER_STORAGE_KEY = "mmd-map-provider";

export function getPreferredProvider(): MapProviderId {
  try {
    const v = localStorage.getItem(MAP_PROVIDER_STORAGE_KEY);
    if (v === "google" || v === "mapbox") return v;
  } catch {
    /* ignore */
  }
  return "mapbox";
}

export function setPreferredProvider(id: MapProviderId): void {
  try {
    localStorage.setItem(MAP_PROVIDER_STORAGE_KEY, id);
  } catch {
    /* ignore */
  }
}

export function decodeB64Token(b64: string | undefined | null): string {
  if (!b64) return "";
  try {
    return atob(b64);
  } catch {
    return "";
  }
}
